import React, {useState,useEffect,useRef} from 'react'
import {createRoot} from 'react-dom/client'
import {Home,Shirt,Instagram,ShoppingBag,Wallet,Users,Plus,ArrowUpRight,ArrowLeft,ArrowRight,Check,ChevronRight,Camera,Search,MessageSquare,Download,X,CheckCircle2,Clock,MapPin,Receipt,SlidersHorizontal,Eye,RotateCcw,WifiOff,AlertCircle,Copy,Share2,Image as ImageIcon,MoreHorizontal,Package,ExternalLink,Trash2} from 'lucide-react'
import {seed,themes,cad,flags,summarize} from './data'
import './style.css'
import {SourcePicker, SourceManager, SourceReport} from './Sources'
import {sourceName, sourceOptions, normalizeSources, reviewTheme} from './sources-model'
import {logos,logoLabel,LogoImage,LogoReview} from './logos'
import PrototypePreview, {inPhoneFrame} from './PrototypePreview'

const KEY='bigmood.prototype.v1'
const copySeed=()=>structuredClone(seed)
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
const initial=read(KEY,null)
const navs=[['today','Today',Home],['inventory','Inventory',Shirt],['posts','Post studio',Instagram],['orders','Orders',ShoppingBag],['money','Money',Wallet],['customers','Customers',Users]]
function Button({children,kind='',...props}){return <button className={`btn ${kind}`} {...props}>{children}</button>}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Photo({item,className='',treatment='original'}){return <div role="img" aria-label={item.name} className={`photo ${className} ${treatment}`} style={item.upload?{backgroundImage:`url(${item.upload})`,backgroundSize:'cover',backgroundPosition:'center'}:{'--px':`${(item.photo%3)*50}%`,'--py':`${Math.floor(item.photo/3)*100}%`}}/>}
function Brand({logo,avatar=false}){if(logo)return <div className="brand selected-logo"><LogoImage id={logo} avatar={avatar}/></div>;return <div className="brand" aria-label="Big Mood Vintage"><span>big<br/>mood</span><small>VINTAGE &amp; DESIGNER</small></div>}
function Status({children}){return <span className={`status s-${String(children).toLowerCase().replaceAll(' ','-')}`}>{children}</span>}
function Render({fn,...props}){return fn(props)}
function App(){
 const [theme,setTheme]=useState(new URLSearchParams(location.search).get('direction')||reviewTheme(initial))
 const [logo,setLogo]=useState(logos.some(l=>l.id===initial?.logo)?initial.logo:'1a')
 const [data,setData]=useState(normalizeSources(initial?.data||copySeed()))
 const [page,setPage]=useState('today'),[selected,setSelected]=useState(null),[orderId,setOrderId]=useState(null)
 const [sourceFilter,setSourceFilter]=useState('All')
 const [filter,setFilter]=useState('All'),[query,setQuery]=useState(''),[toast,setToast]=useState('')
 const [panel,setPanel]=useState(null),[review,setReview]=useState(read(KEY+'.review',[])),[reviewText,setReviewText]=useState(''),[sentiment,setSentiment]=useState('Change this')
 const [viewer,setViewer]=useState(false),[offline,setOffline]=useState(false),[guide,setGuide]=useState(!read(KEY+'.visited',false)),[customerId,setCustomerId]=useState(null)
 const [storageError,setStorageError]=useState(false),[resetConfirm,setResetConfirm]=useState(false)
 const mainRef=useRef(null)
 const current=data.items.find(i=>i.id===selected), order=data.orders.find(o=>o.id===orderId)
 const themeKey=themes[theme]?theme:'club'
 const screen=current?`${page}: ${current.name}`:order?`Order ${order.id}`:page
 useEffect(()=>{if(!inPhoneFrame)return;const receive=e=>{if(e.origin!==location.origin||e.source!==window.parent||e.data?.type!=='bigmood:preview')return;if(e.data.action==='theme'&&themes[e.data.value])setTheme(e.data.value);if(e.data.action==='feedback'){setGuide(false);setPanel({type:'feedback'})}if(e.data.action==='logos'){setGuide(false);setPanel(null);setPage('logos');setSelected(null);setOrderId(null)}if(e.data.action==='guide'){setPanel(null);setGuide(true)}};window.addEventListener('message',receive);return()=>window.removeEventListener('message',receive)},[])
 useEffect(()=>{if(inPhoneFrame)window.parent.postMessage({type:'bigmood:theme',theme:themeKey},location.origin)},[themeKey])
 useEffect(()=>{try{localStorage.setItem(KEY,JSON.stringify({theme,data,logo,reviewRevision:2}));setStorageError(false)}catch{setStorageError(true)}},[data,theme,logo])
 useEffect(()=>{try{localStorage.setItem(KEY+'.review',JSON.stringify(review))}catch{setStorageError(true)}},[review])
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t)}},[toast])
 useEffect(()=>{mainRef.current?.focus({preventScroll:true});window.scrollTo(0,0)},[page,selected,orderId])
 const tell=t=>setToast(t)
 const go=p=>{setPage(p);setSelected(null);setOrderId(null);setFilter('All');setSourceFilter('All');setQuery('');setPanel(null)}
 const updateItem=(id,changes)=>setData(d=>({...d,items:d.items.map(i=>i.id===id?{...i,...changes}:i)}))
 const showItem=i=>{setPage('inventory');setSelected(i.id);setPanel(null)}
 const showOrder=o=>{setPage('orders');setOrderId(o.id);setSelected(null);setPanel(null)}
 const saveBlob=(text,name,type='text/plain')=>{const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
 const copy=async t=>{try{await navigator.clipboard.writeText(t);tell('Copied to the clipboard.')}catch{setPanel({type:'copy',text:t})}}
 const reviewContent=()=>`Big Mood Vintage prototype feedback\n\n${review.map((r,i)=>`${i+1}. ${themes[r.theme]?.name} | ${logoLabel(r.logo)} | ${r.screen}\n${r.sentiment}\n${r.text}\n${r.date}\n`).join('\n')}`
 const exportReview=()=>{saveBlob(reviewContent(),'big-mood-feedback.txt');tell('Feedback downloaded. Send the file back to Patrick.')}
 const shareReview=async()=>{const file=new File([reviewContent()],'big-mood-feedback.txt',{type:'text/plain'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'Big Mood feedback'});else exportReview()}catch(e){if(e.name!=='AbortError')exportReview()}}
 const mutate=(fn)=>{if(viewer){tell('Patrick has view-only access in this preview. Switch to Owner to try changes.');return}fn()}
 const stats=summarize(data)
 function exportMoney(){let rows=[['Type','Reference','Date','Amount CAD','Status'],...data.orders.map(o=>['Order',o.id,o.date,o.total,o.status]),...data.expenses.map(e=>['Expense',e.vendor,e.date,e.amount,e.category])];saveBlob(rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'big-mood-sample-records.csv','text/csv');tell('Sample records exported. The finished app will include receipts and inventory reports.')}
 const sampleCaption=i=>`${i.name}\n${cad(i.price)} CAD | Size ${i.size}\n\n${i.notes||'A new find for your wardrobe.'}\nCondition: ${i.condition}. ${i.flaws}\n${i.measurements?i.measurements+'\n':''}\nMessage to reserve ${i.id}. Calgary pickup; ask about local delivery or Canadian shipping. E-transfer within 24 hours of confirmation.`
 function ItemCard({item}){return <button className="item-card" onClick={()=>showItem(item)}><Photo item={item}/><div className="item-meta"><span>{item.id} <span className="dim">/ {item.size}</span></span><Status>{item.status}</Status></div><h3>{item.name}</h3><p className="item-source">{sourceName(data,item.sourcedFrom)}</p><div className="item-bottom"><span>{cad(item.price)} <small>asking</small></span><span className="dim">{item.location||'No location'} <ArrowUpRight size={14}/></span></div></button>}
 function PageTitle({kicker,title,children}){return <div className="page-title"><div>{kicker&&<p className="eyebrow">{kicker}</p>}<h1>{title}</h1></div>{children}</div>}
 function Task({icon:Icon,title,detail,action,onClick}){return <button className="task" onClick={onClick}><span className="task-icon"><Icon size={20}/></span><span className="task-copy"><strong>{title}</strong><small>{detail}</small></span><span className="task-action">{action}<ChevronRight size={17}/></span></button>}
 function Today(){const ready=data.items.filter(i=>i.status==='Ready to list'),unpaid=data.orders.filter(o=>o.status==='Awaiting payment'),old=data.items.filter(i=>i.status==='Listed'&&i.listed&&new Date('2026-09-21')-new Date(i.listed)>30*86400000);return <>
  <PageTitle kicker="Monday, 2026-09-21 · Sample day" title="A good day for a good find."><Button kind="primary" onClick={()=>mutate(()=>setPanel({type:'capture'}))}><Plus size={18}/>Add a find</Button></PageTitle>
  <div className="today-layout"><section className="day-work"><div className="section-line"><h2>Your next moves</h2><span>{ready.length+unpaid.length+old.length} to review</span></div>
   {ready.length>0&&<Task icon={Instagram} title={`${ready.length} ${ready.length===1?'piece is':'pieces are'} ready for Instagram`} detail="Photos, price, caption. One place to finish." action="Prepare" onClick={()=>{setSelected(ready[0].id);setPage('posts')}}/>}
   {unpaid.map(o=><Task key={o.id} icon={Clock} title={`${data.customers.find(c=>c.id===o.customer)?.name} · ${cad(o.total)} pending`} detail={`${o.id} · E-transfer not yet confirmed`} action="Review" onClick={()=>showOrder(o)}/>)}
   {old.length>0&&<Task icon={RotateCcw} title={`${old.length} listing to revisit`} detail="The denim jacket has been listed for over 30 days." action="Take a look" onClick={()=>showItem(old[0])}/>}
   {ready.length+unpaid.length+old.length===0&&<div className="empty"><CheckCircle2/><h3>You’re caught up.</h3><p>Add a new find when you’re ready.</p></div>}
   <div className="day-note"><span className="wordmark-small">big mood, small steps.</span><p>Capture the find now.<br/>Make the listing yours later.</p><Button onClick={()=>mutate(()=>setPanel({type:'capture'}))}>Start with a photo <ArrowRight size={17}/></Button></div>
  </section><aside className="overview"><h2>The business, at a glance</h2><p className="dim">Sample month · CAD</p><dl><div><dt>Money received, less refunds</dt><dd>{cad(stats.revenue)}</dd></div><div><dt>Operating expenses</dt><dd>{cad(stats.overhead)}</dd></div><div><dt>{stats.unknown?'Known-cost result':'Business profit'}</dt><dd>{cad(stats.profit)}</dd></div><div><dt>Stock at recorded cost</dt><dd>{cad(stats.stock)}</dd></div></dl><p className="fine">{data.items.filter(i=>i.cost===null).length} personal item needs a transfer value. Asking prices are not income.</p><Button kind="text" onClick={()=>go('money')}>See the numbers <ArrowUpRight size={17}/></Button></aside></div>
  <section className="recent"><div className="section-line"><h2>On your rail</h2><Button kind="text" onClick={()=>go('inventory')}>All inventory <ArrowRight size={17}/></Button></div><div className="item-grid">{data.items.filter(i=>i.status!=='Sold').slice(0,4).map(i=><ItemCard item={i} key={i.id}/>)}</div></section>
 </>}
 function Inventory(){const filtered=data.items.filter(i=>(filter==='All'||i.status===filter)&&(sourceFilter==='All'||(i.sourcedFrom||'unknown')===sourceFilter)&&(i.name+' '+i.id+' '+i.location).toLowerCase().includes(query.toLowerCase()));return <><PageTitle kicker={`${data.items.length} pieces · One of each`} title="Your inventory"><Button kind="primary" onClick={()=>mutate(()=>setPanel({type:'capture'}))}><Plus size={18}/>Add a find</Button></PageTitle><div className="inventory-toolbar"><label className="search"><Search size={18}/><input aria-label="Search inventory" placeholder="Search a piece, item number or location" value={query} onChange={e=>setQuery(e.target.value)}/></label><Field label="Sourced from"><select value={sourceFilter} onChange={e=>setSourceFilter(e.target.value)}><option value="All">All sources</option>{sourceOptions(data).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Button onClick={()=>setPanel({type:'trip'})}><Receipt size={17}/>Shopping trip</Button></div><SourceManager data={data} setData={setData} disabled={viewer}/><div className="tabs" role="group" aria-label="Inventory status">{['All','Preparing','Ready to list','Listed','Reserved','Sold'].map(f=><button key={f} className={f===filter?'active':''} onClick={()=>setFilter(f)}>{f}<small>{data.items.filter(i=>f==='All'||i.status===f).length}</small></button>)}</div><div className="item-grid full">{filtered.map(i=><ItemCard item={i} key={i.id}/>)}</div>{!filtered.length&&<div className="empty"><Shirt/><h2>No pieces here yet.</h2><p>Try another search or add your first find.</p><Button onClick={()=>{setQuery('');setFilter('All');setSourceFilter('All')}}>Clear filters</Button></div>}</>}
 function ItemDetail(){const i=current;return <><Button kind="text back" onClick={()=>setSelected(null)}><ArrowLeft size={16}/>Inventory</Button><PageTitle kicker={`${i.id} · ${i.source}`} title={i.name}><Status>{i.status}</Status></PageTitle><div className="detail-layout"><div><Photo item={i} className="detail-photo"/><div className="photo-caption">Sample product photograph <span>{i.id}</span></div><Button kind="text" onClick={()=>setPanel({type:'photo',item:i})}><SlidersHorizontal size={16}/>Compare photo treatments</Button></div><div className="detail-content"><div className="price-line"><div><span className="dim">Asking price</span><strong>{cad(i.price)}</strong></div><div><span className="dim">Recorded cost</span><strong>{i.cost===null?'Unknown':cad(i.cost)}</strong></div></div><div className="facts"><div><span>Size</span><strong>{i.size}</strong></div><div><span>Condition</span><strong>{i.condition}</strong></div><div><span>Location</span><strong>{i.location||'Not stored'}</strong></div></div><p className="fine">Sourced from: {sourceName(data,i.sourcedFrom)}</p><p>{i.notes}</p><p className="fine">Condition notes: {i.flaws}</p>{i.measurements&&<p className="fine">{i.measurements}</p>}<div className="price-advice"><span className="eyebrow">Pricing support</span><h3>{i.cost===null?'Confirm cost before calculating profit':`${cad(i.cost+(i.prep||0)+i.target)} suggested minimum`}</h3><p>{i.cost===null?'Original purchase price and transfer value are separate. Unknown is not zero.':`Includes ${cad(i.cost)} purchase cost, ${cad(i.prep||0)} preparation and ${cad(i.target)} target profit. Delivery costs are additional.`}</p><Button onClick={()=>setPanel({type:'research',item:i})}>Explore price estimate <ArrowUpRight size={16}/></Button></div><div className="button-row"><Button kind="primary" disabled={viewer||['Reserved','Sold'].includes(i.status)} onClick={()=>{setPage('posts')}}><Instagram size={17}/>Prepare a post</Button><Button disabled={viewer||['Reserved','Sold'].includes(i.status)} onClick={()=>setPanel({type:'reserve',item:i})}>Reserve for buyer</Button></div><Button kind="text" disabled={viewer} onClick={()=>setPanel({type:'edit',item:i})}>Edit item details</Button></div></div></>}
 function Posts(){const i=current||data.items.find(x=>!['Sold','Reserved'].includes(x.status))||data.items[0];const [caption,setCaption]=useState(i.caption||sampleCaption(i));const [format,setFormat]=useState('Post');const [treatment,setTreatment]=useState('original');return <><PageTitle kicker="Prepare here. Publish in Instagram." title="Make it a post."><Button onClick={()=>{setSelected(null);go('inventory')}}>Choose another piece</Button></PageTitle><div className="post-layout"><section className="post-canvas"><div className="tabs narrow">{['Post','Story'].map(f=><button key={f} onClick={()=>setFormat(f)} className={format===f?'active':''}>{f}</button>)}</div><div className={`social-preview ${format==='Story'?'story':''}`}><div className="social-head"><Brand logo={logo} avatar/><span>Big Mood Vintage<small>Sample preview</small></span><MoreHorizontal size={20}/></div><Photo item={i} treatment={treatment}/>{format==='Story'&&<div className="story-price"><span>{i.name}</span><strong>{cad(i.price)} CAD</strong><small>Message to reserve · {i.id}</small></div>}{format==='Post'&&<div className="social-caption"><strong>{i.name}</strong><p>{cad(i.price)} CAD · {i.size} · {i.id}</p></div>}</div><div className="segmented">{['original','bright'].map(t=><button key={t} className={treatment===t?'active':''} onClick={()=>setTreatment(t)}>{t==='original'?'Original light':'Brighter preview'}</button>)}</div><p className="fine">Compare lighting only. Keep real colours and flaws visible.</p></section><section><Field label="Item"><select value={i.id} onChange={e=>setSelected(e.target.value)}>{data.items.map(x=><option key={x.id} value={x.id}>{x.id} · {x.name}</option>)}</select></Field><Field label="Caption" hint="Demo draft from item details. Edit it to sound like you."><textarea rows="12" value={caption} onChange={e=>setCaption(e.target.value)}/></Field><div className="button-row"><Button disabled={viewer} onClick={()=>{updateItem(i.id,{caption});tell('Caption saved to this demo on your device.')}}>Save caption</Button><Button onClick={()=>copy(caption)}><Copy size={16}/>Copy caption</Button></div><div className="publish-steps"><h3>Ready when you are</h3><p>Save your image and caption, then post them in Instagram. Come back to record that it is listed.</p><Button onClick={()=>downloadPost(i,format,treatment)}>Download {format.toLowerCase()} image <Download size={16}/></Button></div><Button kind="primary wide" disabled={viewer||['Sold','Reserved'].includes(i.status)||!i.flaws?.trim()||!i.size?.trim()||i.price<=0} onClick={()=>{updateItem(i.id,{status:'Listed',listed:'2026-09-21',caption});tell('Marked as listed in the demo. Nothing was posted to Instagram.')}}><Check size={18}/>I’ve posted it</Button>{i.status==='Listed'&&<p className="success-text"><CheckCircle2 size={16}/>Listed in the demo. No post was sent.</p>}</section></div></>}
 async function downloadPost(i,format,treatment){try{const im=new window.Image();im.src=i.upload||'/assets/wardrobe.png';await im.decode();const c=document.createElement('canvas');c.width=1080;c.height=format==='Story'?1920:1350;const x=c.getContext('2d');x.fillStyle='#dce5ef';x.fillRect(0,0,c.width,c.height);const sw=i.upload?im.width:im.width/3,sh=i.upload?im.height:im.height/2;const sx=i.upload?0:(i.photo%3)*sw,sy=i.upload?0:Math.floor(i.photo/3)*sh;x.filter=treatment==='bright'?'brightness(1.09)':'none';x.drawImage(im,sx,sy,sw,sh,0,130,1080,1080);x.filter='none';x.fillStyle='#691e25';x.font='48px Georgia';x.fillText('big mood vintage',60,88);x.font='36px sans-serif';x.fillText(i.name,60,1280,960);if(format==='Story'){x.font='64px Georgia';x.fillText(cad(i.price)+' CAD',60,1440);x.font='32px sans-serif';x.fillText('Message to reserve · '+i.id,60,1520);x.fillText('Sample prototype image',60,1810)}const blob=await new Promise(r=>c.toBlob(r));const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`${i.id}-${format.toLowerCase()}-sample.png`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);tell('Sample image downloaded.')}catch{tell('Image could not be downloaded. Try again after the photo loads.')}}
 function Orders(){return <><PageTitle kicker="Enquiry to handoff" title="Keep every order clear."><Button onClick={()=>go('inventory')}>Reserve an item <Plus size={17}/></Button></PageTitle><div className="tabs">{['All','Awaiting payment','Paid','Completed','Cancelled','Refunded'].map(f=><button className={filter===f?'active':''} key={f} onClick={()=>setFilter(f)}>{f}</button>)}</div><div className="order-list">{data.orders.filter(o=>filter==='All'||o.status===filter).map(o=><button className="order-row" key={o.id} onClick={()=>showOrder(o)}><Photo item={data.items.find(i=>i.id===o.items[0])}/><span><strong>{data.customers.find(c=>c.id===o.customer)?.name}</strong><small>{o.id} · {o.items.length} {o.items.length===1?'piece':'pieces'} · {o.method}</small><Status>{o.status}</Status></span><strong>{cad(o.total-(o.refund||0))}</strong><ChevronRight size={18}/></button>)}</div>{!data.orders.some(o=>filter==='All'||o.status===filter)&&<div className="empty"><ShoppingBag/><h3>No orders in this view.</h3><p>Reservations start from an inventory item.</p></div>}</>}
 function OrderDetail(){const o=order,c=data.customers.find(c=>c.id===o.customer),items=data.items.filter(i=>o.items.includes(i.id));const [ref,setRef]=useState(o.reference),[checked,setChecked]=useState(false),[when,setWhen]=useState(o.appointment),[notes,setNotes]=useState(o.instructions),[actual,setActual]=useState(o.actualShipping||0);const update=changes=>setData(d=>({...d,orders:d.orders.map(x=>x.id===o.id?{...x,...changes}:x)}));return <><Button kind="text back" onClick={()=>setOrderId(null)}><ArrowLeft size={16}/>Orders</Button><PageTitle kicker={`${o.id} · ${o.date}`} title={`An order for ${c.name}`}><Status>{o.status}</Status></PageTitle><div className="order-detail"><section>{items.map(i=><div className="order-product" key={i.id}><Photo item={i}/><div><h3>{i.name}</h3><p>{i.id} · Size {i.size}</p><span>{cad(i.price)}</span></div></div>)}<div className="totals"><div><span>Item asking prices</span><span>{cad(items.reduce((s,i)=>s+i.price,0))}</span></div><div><span>Agreed discount</span><span>{cad(o.discount)}</span></div><div><span>Delivery / shipping charged</span><span>{cad(o.fee)}</span></div><div className="total"><span>Order total</span><span>{cad(o.total)}</span></div>{o.refund>0&&<div><span>Refund recorded</span><span>{cad(o.refund)}</span></div>}</div><div className="customer-strip"><Users size={21}/><div><strong>{c.name}</strong><p>{c.handle}</p></div><Button onClick={()=>{setCustomerId(c.id);go('customers')}}>Customer record</Button></div></section><section className="order-actions">{o.status==='Awaiting payment'&&<><h2>Confirm the e-transfer</h2><p>Check the deposit in your bank account before recording payment.</p><p className="notice"><Clock size={17}/>Payment due {o.deadline.replace('T',' at ')} MT. Review before releasing an overdue reservation.</p><Field label="Bank reference (optional)"><input value={ref} onChange={e=>setRef(e.target.value)} placeholder="Reference from your deposit"/></Field><label className="check-row"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/>I checked that the full amount arrived.</label><Button kind="primary wide" disabled={!checked||viewer} onClick={()=>{update({status:'Paid',reference:ref});items.forEach(i=>updateItem(i.id,{status:'Sold'}));tell('Payment recorded in the demo. No bank connection was used.')}}>Confirm {cad(o.total)} received</Button><Button kind="text" onClick={()=>copy(`Your ${o.id} reservation is confirmed. Total: ${cad(o.total)} CAD. Please e-transfer within 24 hours. I will send my payment address in this conversation. ${o.method} details will follow.`)}>Copy payment message <Copy size={16}/></Button><Button kind="text danger" disabled={viewer} onClick={()=>setPanel({type:'cancel',order:o})}>Cancel reservation</Button></>}
 {['Paid','Completed','Refunded'].includes(o.status)&&<><div className="notice success"><CheckCircle2 size={20}/><span>Payment recorded{ref?` · ${ref}`:''}. {o.refund>0?`${cad(o.refund)} refunded.`:'Ready for the next step.'}</span></div><h2>{o.method==='Shipping'?'Shipping details':'Arrange the handoff'}</h2><Field label="Date and time, MT"><input type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)}/></Field><Field label="Address or handoff instructions" hint="Use sample details in this public prototype."><textarea rows="3" value={notes} onChange={e=>setNotes(e.target.value)}/></Field>{o.method!=='Local pickup'&&<Field label="Actual delivery / postage cost, CAD"><input type="number" min="0" step="0.01" value={actual} onChange={e=>setActual(Number(e.target.value))}/></Field>}<div className="button-row"><Button disabled={viewer} onClick={()=>{update({appointment:when,instructions:notes,actualShipping:actual});tell('Handoff details saved.')}}>Save details</Button><Button onClick={()=>copy(`Your ${o.id} order is paid. ${o.method}: ${when?when.replace('T',' at ')+' MT':''}. ${notes}`)}>Copy message</Button></div>{o.status==='Paid'&&<Button kind="primary wide" disabled={viewer} onClick={()=>{update({status:'Completed',appointment:when,instructions:notes,actualShipping:actual});tell('Order completed. Your sample profit view is updated.')}}>Mark {o.method==='Shipping'?'shipped':o.method==='Local delivery'?'delivered':'collected'} <Check size={17}/></Button>}<Button kind="text" disabled={viewer||o.refund>=o.total} onClick={()=>setPanel({type:'refund',order:o})}>Record a refund</Button></>}
 {o.status==='Cancelled'&&<div className="notice">Reservation cancelled. Items are available again.</div>}</section></div></>}
 function Money(){return <><PageTitle kicker="Sample month · All amounts in CAD" title="Know what you’re making."><Button kind="primary" disabled={viewer} onClick={()=>setPanel({type:'expense'})}><Plus size={18}/>Add expense</Button></PageTitle><div className="money-layout"><section><div className="section-line"><h2>Business result</h2><Button kind="text" onClick={exportMoney}><Download size={16}/>Export</Button></div><dl className="money-statement"><div><dt>Money received, less refunds</dt><dd>{cad(stats.revenue)}</dd></div><div><dt>Cost of sold items and preparation</dt><dd>{cad(stats.cost)}</dd></div><div><dt>Delivery and postage costs</dt><dd>{cad(stats.shipping)}</dd></div><div><dt>Operating expenses</dt><dd>{cad(stats.overhead)}</dd></div><div className="statement-total"><dt>{stats.unknown?'Known-cost result':'Business profit'}</dt><dd>{cad(stats.profit)}</dd></div></dl><p className="fine">{stats.unknown?'Some sold-item costs are unknown. This is not a complete profit figure.':'Recorded sales less item costs, postage and operating expenses. Before personal income tax.'} Sample figures, not tax accounts.</p><div className="money-other"><div><span>Awaiting payment</span><strong>{cad(stats.unpaid)}</strong></div><div><span>Stock at recorded cost</span><strong>{cad(stats.stock)}</strong></div></div><div className="notice"><AlertCircle size={19}/>Personal items with an unconfirmed transfer value are excluded from stock cost. Asking prices are never counted as earnings.</div></section><section><div className="section-line"><h2>Expenses</h2><Receipt size={20}/></div>{data.expenses.map(e=><div className="expense-row" key={e.id}><Receipt size={19}/><div><strong>{e.vendor}</strong><small>{e.category} · {e.date}{e.receipt?' · Receipt attached':''}</small></div><span>{cad(e.amount)}</span></div>)}<Button kind="text" disabled={viewer} onClick={()=>setPanel({type:'expense'})}>Capture a receipt <ArrowRight size={16}/></Button><div className="account-note"><h3>A small business, clearly recorded.</h3><p>GST/HST collection is off. Owner funding is kept separate from sales. Bank matching and tax filing are outside this prototype.</p></div></section></div><SourceReport data={data}/></>}
 function Customers(){const c=data.customers.find(c=>c.id===customerId);const [note,setNote]=useState('');const [contact,setContact]=useState(c?{email:c.email,phone:c.phone}:{email:'',phone:''});return <><PageTitle kicker="Private business records" title={c?c.name:'Know your buyers.'}><Button onClick={()=>setPanel({type:'customer'})}>Add customer <Plus size={17}/></Button></PageTitle>{c?<><Button kind="text back" onClick={()=>setCustomerId(null)}><ArrowLeft size={16}/>All customers</Button><div className="customer-detail"><section><p className="handle">{c.handle}</p><div className="form-grid"><Field label="Email (optional)"><input type="email" value={contact.email} onChange={e=>setContact({...contact,email:e.target.value})}/></Field><Field label="Phone (optional)"><input type="tel" value={contact.phone} onChange={e=>setContact({...contact,phone:e.target.value})}/></Field></div><Button disabled={viewer} onClick={()=>{setData(d=>({...d,customers:d.customers.map(x=>x.id===c.id?{...x,...contact}:x)}));tell('Customer contact details saved.')}}>Save contact details</Button><h2 className="space-top">Private flags</h2><p className="fine">Optional. Describe behaviour, not the person. These appear when you create an order.</p><div className="flag-options">{flags.map(f=><label key={f}><input type="checkbox" disabled={viewer} checked={c.flags.includes(f)} onChange={()=>setData(d=>({...d,customers:d.customers.map(x=>x.id===c.id?{...x,flags:x.flags.includes(f)?x.flags.filter(v=>v!==f):[...x.flags,f]}:x)}))}/>{f}</label>)}</div></section><section><h2>Dated notes</h2>{c.notes.map((n,j)=><div className="note-record" key={j}><small>{n.date} · {n.order||'Customer record'}</small><p>{n.text}</p></div>)}<Field label="Add a factual note"><textarea value={note} onChange={e=>setNote(e.target.value)} rows="3" placeholder="What happened, and on which order?"/></Field><Button disabled={!note.trim()||viewer} onClick={()=>{setData(d=>({...d,customers:d.customers.map(x=>x.id===c.id?{...x,notes:[...x.notes,{text:note,date:'2026-09-21',order:''}]}:x)}));setNote('')}}>Save note</Button><h2 className="space-top">Order history</h2>{data.orders.filter(o=>o.customer===c.id).map(o=><Task key={o.id} icon={ShoppingBag} title={`${o.id} · ${cad(o.total)}`} detail={o.status} action="Open" onClick={()=>showOrder(o)}/>)}{!data.orders.some(o=>o.customer===c.id)&&<p className="fine">No orders in this demo yet.</p>}</section></div></>:<div className="customer-list">{data.customers.map(c=><button className="customer-row" key={c.id} onClick={()=>setCustomerId(c.id)}><span className="avatar">{c.name[0]}</span><span><strong>{c.name}</strong><small>{c.handle}</small><span className="flags">{c.flags.map(f=><Status key={f}>{f}</Status>)}</span></span><ChevronRight size={18}/></button>)}</div>}</>}
 function PublicPage(){return <><div className="public-preview"><div className="public-nav"><Brand logo={logo}/><span>Calgary, Alberta</span></div><div className="public-hero"><div><p className="eyebrow">Vintage &amp; designer</p><h1>Your next<br/>good find.</h1><p>Clothing with character.<br/>Handpicked in Calgary.</p><Button kind="primary" onClick={()=>setPanel({type:'public-info'})}>Find us on Instagram <ArrowUpRight size={18}/></Button></div><Photo item={data.items[0]}/></div><div className="public-bottom"><h2>See something you love?</h2><p>Message us on Instagram to ask about availability. E-transfer after your reservation is confirmed. Local pickup, with delivery and Canadian shipping by arrangement.</p></div><div className="public-footer">bigmoodvintage.com <span>Draft information page</span></div></div><p className="fine">Website concept only. The Instagram profile link, delivery fees, shipping and return policy need her review.</p></>}
 function Dialog({children,title,onClose}){const ref=useRef(null);useEffect(()=>{const before=document.activeElement;ref.current?.showModal();return()=>{before?.focus?.()}},[]);return <dialog ref={ref} onCancel={e=>{e.preventDefault();onClose()}} className="dialog"><div className="dialog-head"><h2>{title}</h2><button className="icon-btn" aria-label="Close dialog" onClick={onClose}><X/></button></div><div className="dialog-body">{children}</div></dialog>}
 function Panel(){const close=()=>setPanel(null);if(!panel)return null;
 if(panel.type==='capture'||panel.type==='edit')return <Render fn={Capture} edit={panel.item} close={close}/>;
 if(panel.type==='reserve')return <Render fn={Reserve} item={panel.item} close={close}/>;
 if(panel.type==='expense'||panel.type==='trip')return <Render fn={Expense} trip={panel.type==='trip'} close={close}/>;
 if(panel.type==='research')return <Render fn={Research} item={panel.item} close={close}/>;
 if(panel.type==='customer')return <Render fn={NewCustomer} close={close}/>;
 if(panel.type==='refund')return <Render fn={Refund} order={panel.order} close={close}/>;
 if(panel.type==='photo')return <Render fn={Dialog} title="Compare the photograph" onClose={close}><p>Same sample item, two lighting treatments. Tell us which you prefer using the feedback button.</p><div className="photo-compare"><div><Photo item={panel.item}/><p>Original light</p></div><div><Photo item={panel.item} treatment="bright"/><p>Brighter light</p></div></div><p className="fine">This is a lighting preview. Background removal and real photo editing are not implemented.</p><Button onClick={()=>{close();setPanel({type:'feedback'})}}>Leave photo feedback</Button></Render>;
 if(panel.type==='cancel')return <Render fn={Dialog} title="Cancel this reservation?" onClose={close}><p>The demo items will become available again. No customer message will be sent.</p><div className="button-row"><Button onClick={close}>Keep reservation</Button><Button kind="primary" onClick={()=>{const o=panel.order;setData(d=>({...d,orders:d.orders.map(x=>x.id===o.id?{...x,status:'Cancelled'}:x),items:d.items.map(i=>o.items.includes(i.id)?{...i,status:'Listed'}:i)}));close();tell('Reservation cancelled. Items are available again.')}}>Cancel reservation</Button></div></Render>;
 if(panel.type==='public-info')return <Render fn={Dialog} title="Instagram link to confirm" onClose={close}><p>This button will open her actual Instagram profile in the finished page. We have not assumed a username from the profile image.</p><p>Customers will message her there. This first website has no catalogue or checkout.</p><Button onClick={close}>Back to the page</Button></Render>;
 if(panel.type==='copy')return <Render fn={Dialog} title="Copy your text" onClose={close}><p>Your browser did not allow automatic copying. Select the text below.</p><textarea readOnly rows="10" value={panel.text} onFocus={e=>e.target.select()}/></Render>;
 if(panel.type==='feedback')return <Render fn={Dialog} title="What do you think?" onClose={close}><p className="feedback-context">{themes[themeKey].name} · {logoLabel(logo)} · {screen}</p><div className="segmented">{['Like this','Change this','Question'].map(s=><button key={s} className={sentiment===s?'active':''} onClick={()=>setSentiment(s)}>{s}</button>)}</div><Field label="Your note"><textarea rows="4" autoFocus placeholder="What feels right? What would make this easier?" value={reviewText} onChange={e=>setReviewText(e.target.value)}/></Field><Button kind="primary wide" disabled={!reviewText.trim()} onClick={()=>{setReview(r=>[...r,{theme:themeKey,logo,screen,sentiment,text:reviewText.trim(),date:new Date().toLocaleString('en-CA',{timeZone:'America/Edmonton'})+' MT'}]);setReviewText('');tell('Note saved on this device. Share your feedback when you’re finished.');close()}}>Save note</Button><div className="section-line space-top"><h3>Your notes ({review.length})</h3>{review.length>0&&<Button kind="text" onClick={shareReview}><Share2 size={16}/>Share all</Button>}</div><p className="fine">Notes stay in this browser until you share or download them. They are not automatically sent to Patrick. Avoid personal information.</p>{review.map((r,j)=><div className="note-record" key={j}><div className="section-line"><small>{themes[r.theme].name} · {logoLabel(r.logo)} · {r.screen}</small><button className="icon-btn" aria-label={`Delete feedback ${j+1}`} onClick={()=>setReview(old=>old.filter((_,k)=>k!==j))}><Trash2 size={15}/></button></div><strong>{r.sentiment}</strong><p>{r.text}</p></div>)}{review.length>0&&<div className="button-row"><Button onClick={exportReview}>Download feedback file <Download size={16}/></Button><Button onClick={()=>copy(reviewContent())}>Copy all notes <Copy size={16}/></Button></div>}</Render>;
 return null}
 function Capture({edit,close}){const [v,setV]=useState(edit||{name:'',cost:'',price:48,size:'Unknown',condition:'Good',flaws:'',notes:'',location:'',source:'Thrift purchase',photo:0,target:20,prep:0});const [used,setUsed]=useState(!!edit),[error,setError]=useState('');const set=(k,x)=>setV(a=>({...a,[k]:x}));const file=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024){setError('Choose an image smaller than 3 MB, or use the sample photo.');return}const r=new FileReader();r.onload=()=>{setV(a=>({...a,upload:r.result}));setUsed(true)};r.readAsDataURL(f)};const save=e=>{e.preventDefault();if(!v.name.trim()){setError('Give this find a name.');return}if(v.status==='Ready to list'&&(!v.size.trim()||!v.flaws.trim()||Number(v.price)<=0)){setError('A ready listing needs a price, tagged size or unknown, condition, and known flaws.');return}if(v.source==='Thrift purchase'&&(v.cost===''||Number(v.cost)<0)){setError('Enter the purchase cost, including zero if it was free.');return}const it={...v,name:v.name.trim(),cost:v.source==='Personal item'?(v.cost===''?null:Number(v.cost)):Number(v.cost),price:Number(v.price)||0,date:edit?.date||'2026-09-21',id:edit?.id||`BM-${String(Date.now()).slice(-5)}`,status:v.status||'Preparing',offline:offline};if(edit)updateItem(edit.id,it);else setData(d=>({...d,items:[it,...d.items]}));close();showItem(it);tell(offline?'Find saved on this device. Offline queue is demonstrated only.':'Find saved. Finish the listing when you’re ready.')};return <Render fn={Dialog} title={edit?'Edit this piece':'Save a new find'} onClose={close}><form onSubmit={save}><div className="capture-top"><Photo item={v}/><div><p>A photo and what you paid.<br/>The rest can wait.</p><label className="btn"><Camera size={17}/>Choose a photo<input className="sr-only" type="file" accept="image/*" onChange={file}/></label><Button type="button" kind="text" onClick={()=>{setUsed(true);setV(a=>({...a,name:'Burgundy scallop cardigan',cost:12,photo:0,flaws:'Light pilling at cuffs.'}))}}>Use sample find</Button></div></div>{!used&&<p className="fine">Showing a sample photo until you choose one. Uploaded images remain in this browser.</p>}<Field label="Item name"><input value={v.name} onChange={e=>set('name',e.target.value)} required placeholder="What did you find?"/></Field><div className="form-grid"><Field label="Acquisition type"><select value={v.source} onChange={e=>{set('source',e.target.value);set('cost','');set('sourcedFrom',e.target.value==='Personal item'?'personal':'unknown')}}><option>Thrift purchase</option><option>Personal item</option></select></Field><Field label={v.source==='Personal item'?'Transfer value, CAD (optional)':'What you paid, CAD'}><input type="number" min="0" step="0.01" value={v.cost??''} onChange={e=>set('cost',e.target.value)}/></Field></div>{v.source==='Personal item'&&<p className="notice">Leave the transfer value blank if unconfirmed. Original retail cost is not automatically the business cost.</p>}<SourcePicker data={data} setData={setData} value={v.sourcedFrom||'unknown'} onChange={value=>set('sourcedFrom',value)} disabled={viewer} personal={v.source==='Personal item'}/><Field label="Notes (optional)"><textarea rows="2" value={v.notes} onChange={e=>set('notes',e.target.value)} placeholder="Condition, maker, anything to remember"/></Field><Field label="Storage location (optional)"><input value={v.location} onChange={e=>set('location',e.target.value)} placeholder="Rack 1 or Bin 2"/></Field>{edit&&<><div className="form-grid"><Field label="Asking price, CAD"><input type="number" min="0" value={v.price} onChange={e=>set('price',e.target.value)}/></Field><Field label="Tagged size"><input value={v.size} onChange={e=>set('size',e.target.value)} required/></Field></div><Field label="Condition"><select value={v.condition} onChange={e=>set('condition',e.target.value)}><option>Very good</option><option>Good</option><option>Fair</option></select></Field><Field label="Known flaws, or no known flaws"><textarea value={v.flaws} onChange={e=>set('flaws',e.target.value)}/></Field><Field label="Measurements (optional)"><input value={v.measurements||''} onChange={e=>set('measurements',e.target.value)}/></Field><div className="form-grid"><Field label="Target profit, CAD"><input type="number" min="0" value={v.target} onChange={e=>set('target',Number(e.target.value))}/></Field><Field label="Preparation cost, CAD"><input type="number" min="0" step="0.01" value={v.prep} onChange={e=>set('prep',Number(e.target.value))}/></Field></div><label className="check-row"><input type="checkbox" checked={v.status==='Ready to list'} disabled={['Sold','Reserved'].includes(v.status)} onChange={e=>set('status',e.target.checked?'Ready to list':'Preparing')}/>Ready to list</label></>}{error&&<p role="alert" className="error">{error}</p>}<Button kind="primary wide" type="submit" disabled={viewer}>{offline?'Save on this device':'Save find'}</Button><p className="fine">Demo only. AI identification and background syncing are not connected.</p></form></Render>}
 function Reserve({item,close}){const [cid,setCid]=useState(data.customers[0].id),[ids,setIds]=useState([item.id]),[discount,setDiscount]=useState(0),[fee,setFee]=useState(0),[method,setMethod]=useState('Local pickup'),[deadline,setDeadline]=useState('2026-09-22T18:00');const c=data.customers.find(x=>x.id===cid),pieces=data.items.filter(i=>ids.includes(i.id)),subtotal=pieces.reduce((s,i)=>s+i.price,0),min=pieces.reduce((s,i)=>s+(i.cost??0)+(i.prep||0)+i.target,0),total=subtotal-Number(discount)+Number(fee);return <Render fn={Dialog} title="Reserve for a buyer" onClose={close}><form onSubmit={e=>{e.preventDefault();if(total<0)return;const o={id:`BM-${String(Date.now()).slice(-5)}`,items:ids,customer:cid,total,discount:Number(discount),fee:Number(fee),method,status:'Awaiting payment',deadline,date:'2026-09-21',appointment:'',instructions:'',reference:'',refund:0,actualShipping:0};setData(d=>({...d,orders:[o,...d.orders],items:d.items.map(i=>ids.includes(i.id)?{...i,status:'Reserved'}:i)}));close();showOrder(o);tell('Reserved. Payment is still pending.')}}><Field label="Customer"><select value={cid} onChange={e=>setCid(e.target.value)}>{data.customers.map(c=><option value={c.id} key={c.id}>{c.name} · {c.handle}</option>)}</select></Field>{c.flags.length>0&&<div className="notice"><AlertCircle size={20}/><div><strong>Customer reminder</strong><p>{c.flags.join(' · ')}</p>{c.notes.slice(-1).map(n=><small key={n.date}>{n.date}: {n.text}</small>)}<p>You decide whether to proceed.</p></div></div>}<details><summary>Add another piece to this order</summary>{data.items.filter(i=>!['Sold','Reserved'].includes(i.status)).map(i=><label className="check-row" key={i.id}><input type="checkbox" checked={ids.includes(i.id)} disabled={i.id===item.id} onChange={e=>setIds(a=>e.target.checked?[...a,i.id]:a.filter(x=>x!==i.id))}/>{i.name} · {cad(i.price)}</label>)}</details><Field label="How will it get to the buyer?"><select value={method} onChange={e=>setMethod(e.target.value)}><option>Local pickup</option><option>Local delivery</option><option>Shipping</option></select></Field><div className="form-grid"><Field label="Agreed discount, CAD"><input type="number" min="0" max={subtotal} step="0.01" value={discount} onChange={e=>setDiscount(e.target.value)} required/></Field><Field label="Agreed delivery / shipping, CAD"><input type="number" min="0" step="0.01" value={fee} onChange={e=>setFee(e.target.value)} required/></Field></div>{method!=='Local pickup'&&<p className="fine">Fee approach is an open review decision. Enter a sample agreed fee here.</p>}<Field label="Payment deadline, MT"><input type="datetime-local" value={deadline} onChange={e=>setDeadline(e.target.value)} required/></Field>{pieces.some(i=>i.cost===null)?<p className="notice">An item has an unknown cost. Profit cannot be confirmed.</p>:<p className={subtotal-discount<min?'notice warning':'notice'}>{subtotal-discount<min?'Below the suggested minimum. ':''}Expected item contribution: {cad(subtotal-discount-pieces.reduce((s,i)=>s+i.cost+(i.prep||0),0))}, before delivery and overhead. Target minimum: {cad(min)}.</p>}<div className="section-line"><h3>Total due</h3><strong>{cad(total)} CAD</strong></div><Button kind="primary wide" type="submit" disabled={viewer||total<0}>Confirm reservation</Button><p className="fine">E-transfer only. Nothing is sent to the customer automatically.</p></form></Render>}
 function Expense({trip,close}){const [tripSource,setTripSource]=useState('unknown');const [stage,setStage]=useState('capture'),[vendor,setVendor]=useState(trip?'Neighbourhood thrift shop':'Packaging supplies'),[amount,setAmount]=useState(trip?'24':'8.50'),[date,setDate]=useState('2026-09-21'),[category,setCategory]=useState('Packaging'),[a,setA]=useState('12'),[b,setB]=useState('12'),[fileName,setFileName]=useState('Sample receipt'),[error,setError]=useState('');return <Render fn={Dialog} title={trip?'One trip, one receipt':'Capture an expense'} onClose={close}>{stage==='capture'?<><div className="receipt-capture"><Receipt size={38}/><h3>Photograph now. Review next.</h3><p>Borrowing Ledger’s capture and review workflow.</p><label className="btn"><Camera size={17}/>Choose receipt<input type="file" accept="image/*,application/pdf" className="sr-only" onChange={e=>{if(e.target.files[0]){setFileName(e.target.files[0].name);setStage('review')}}}/></label><Button kind="primary" onClick={()=>setStage('review')}>Try sample receipt <ArrowRight size={17}/></Button></div><p className="fine">Extraction is simulated. No file is uploaded or sent to AI. Uploaded receipt contents are not read in this demo.</p></>:<form onSubmit={e=>{e.preventDefault();if(Number(amount)<=0){setError('Enter an amount greater than zero.');return}if(trip&&Math.abs(Number(a)+Number(b)-Number(amount))>0.009){setError('Item costs must add up to the receipt total.');return}if(trip){const id=Date.now();setData(d=>({...d,items:[...d.items,...[{name:'Scallop cardigan from shopping trip',cost:Number(a),photo:0},{name:'Cream knit from shopping trip',cost:Number(b),photo:3}].map((i,j)=>({...i,id:`BM-${String(id).slice(-5)}-${j}`,price:0,size:'Unknown',condition:'Good',flaws:'To check',notes:`Receipt: ${vendor}`,source:'Thrift purchase',sourcedFrom:tripSource,date,status:'Preparing',location:'',target:20,prep:0}))]}))}else setData(d=>({...d,expenses:[...d.expenses,{id:String(Date.now()),vendor,amount:Number(amount),date,category,receipt:fileName==='Sample receipt'}]}));close();go(trip?'inventory':'money');tell(trip?'Trip saved as two inventory purchases. No duplicate expense was added.':'Expense reviewed and saved in the demo.')}}><div className="receipt-slip"><span>{fileName}</span><h3>{vendor}</h3><p>{date}</p><div><span>Sample total</span><strong>{cad(Number(amount))}</strong></div><small>DEMO RECEIPT · CHECK EVERY FIELD</small></div><p className="notice">Review suggested fields before saving. These are sample values, not extracted receipt data.</p>{trip&&<SourcePicker data={data} setData={setData} value={tripSource} onChange={setTripSource} disabled={viewer}/>}<Field label="Supplier"><input value={vendor} onChange={e=>setVendor(e.target.value)} required/></Field><div className="form-grid"><Field label="Date"><input type="date" value={date} onChange={e=>setDate(e.target.value)} required/></Field><Field label="Receipt total, CAD"><input type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} required/></Field></div>{trip?<><h3>Allocate the purchase</h3><p className="fine">Includes shared discounts and charges. Assigned item costs must equal the receipt total.</p><div className="form-grid"><Field label="Cardigan cost, CAD"><input type="number" min="0" step="0.01" value={a} onChange={e=>setA(e.target.value)} required/></Field><Field label="Cream knit cost, CAD"><input type="number" min="0" step="0.01" value={b} onChange={e=>setB(e.target.value)} required/></Field></div><Button type="button" onClick={()=>{setA((Math.floor(Number(amount)*100/2)/100).toFixed(2));setB((Number(amount)-Math.floor(Number(amount)*100/2)/100).toFixed(2))}}>Split equally</Button><p className="fine">Assigned {cad(Number(a)+Number(b))} of {cad(Number(amount))}</p></>:<Field label="Category"><select value={category} onChange={e=>setCategory(e.target.value)}>{['Packaging','Cleaning','Postage','Website','Advertising','Other'].map(x=><option key={x}>{x}</option>)}</select></Field>}{error&&<p className="error" role="alert">{error}</p>}<Button kind="primary wide" type="submit" disabled={viewer}>Confirm and save</Button></form>}</Render>}
 function Research({item,close}){const [stage,setStage]=useState('quick');return <Render fn={Dialog} title="A price with context" onClose={close}><div className="research-item"><Photo item={item}/><div><p>{item.name}</p><h3>{cad(item.price-8)} to {cad(item.price+10)} CAD</h3><Status>Sample AI estimate</Status></div></div>{stage==='quick'&&<><p>Based on a sample identification, not a live search. Check material, condition and maker before relying on any estimate.</p><div className="price-advice"><h3>Look for completed sales</h3><p>Deeper research would prioritize comparable sold items and show sources, dates and currencies.</p><p>Illustrative request cost: C$0.20<br/>Illustrative monthly research cap: C$5.00<br/>Demo usage: {cad(data.researchSpent)} / C$5.00</p><p className="fine">These illustrate the spending controls, not provider pricing. This prototype costs nothing to research.</p><Button kind="primary" disabled={offline||data.researchSpent>=5} onClick={()=>{setData(d=>({...d,researchSpent:Math.min(5,d.researchSpent+0.2)}));setStage('result')}}>Confirm sample research</Button>{offline&&<p>Reconnect to use research. The offline setting is a simulation.</p>}</div></>}{stage==='result'&&<><div className="notice warning"><AlertCircle size={22}/><div><h3>Not enough reliable evidence.</h3><p>No verified recent sold comparisons are connected in this demo. The AI estimate remains separate, not a researched market value.</p></div></div><p>In the finished app, any available findings will appear with their sources. Asking prices will be labelled as asking prices.</p><Button onClick={close}>Keep my asking price</Button></>}</Render>}
 function NewCustomer({close}){const [name,setName]=useState(''),[handle,setHandle]=useState(''),[email,setEmail]=useState(''),[phone,setPhone]=useState('');return <Render fn={Dialog} title="Add a customer" onClose={close}><form onSubmit={e=>{e.preventDefault();const c={id:String(Date.now()),name:name.trim(),handle,email,phone,flags:[],notes:[],address:''};setData(d=>({...d,customers:[...d.customers,c]}));setCustomerId(c.id);close();go('customers')}}><p className="fine">Use fictional details in the prototype.</p><Field label="Name"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Instagram handle"><input required value={handle} onChange={e=>setHandle(e.target.value)} placeholder="@username"/></Field><Field label="Email (optional)"><input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label="Phone (optional)"><input type="tel" value={phone} onChange={e=>setPhone(e.target.value)}/></Field><Button kind="primary wide" disabled={viewer} type="submit">Save customer</Button></form></Render>}
 function Refund({order:o,close}){const [amount,setAmount]=useState(o.total-(o.refund||0)),[reason,setReason]=useState(''),[restock,setRestock]=useState(false),[done,setDone]=useState(false);return <Render fn={Dialog} title="Record a refund" onClose={close}><form onSubmit={e=>{e.preventDefault();const refund=(o.refund||0)+Number(amount);setData(d=>({...d,orders:d.orders.map(x=>x.id===o.id?{...x,refund,refundReason:reason,status:refund>=o.total?'Refunded':x.status,restocked:restock||x.restocked}:x),items:d.items.map(i=>restock&&o.items.includes(i.id)?{...i,status:'Preparing'}:i)}));close();tell('Refund recorded. No money was moved by this prototype.')}}><Field label="Refund amount, CAD"><input type="number" min="0.01" max={o.total-(o.refund||0)} step="0.01" required value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field label="Reason"><textarea required value={reason} onChange={e=>setReason(e.target.value)} rows="3"/></Field><label className="check-row"><input type="checkbox" checked={restock} onChange={e=>setRestock(e.target.checked)}/>All items in this order returned and can go back into preparation.</label><label className="check-row"><input type="checkbox" checked={done} onChange={e=>setDone(e.target.checked)}/>I sent the refund outside the app.</label><p className="fine">Demo: restocking applies to the entire order. Item-level return selection belongs in the working app.</p><Button kind="primary wide" disabled={!done||viewer} type="submit">Record refund</Button></form></Render>}
 return <div className={`app theme-${themeKey}${inPhoneFrame?' phone-screen-app':''}`}>
 <a className="skip" href="#main">Skip to content</a>
 <div className="review-bar"><span className="prototype-label">Prototype <span>· Sample data only</span></span><label className="direction-picker"><span>Direction</span><select aria-label="Visual direction" value={themeKey} onChange={e=>setTheme(e.target.value)}>{Object.entries(themes).map(([k,t])=><option key={k} value={k}>{t.name}</option>)}</select></label><div className="review-actions"><button onClick={()=>go('logos')}>Logo options</button><button onClick={()=>setGuide(true)}>Review guide</button><button className="feedback-button" onClick={()=>setPanel({type:'feedback'})}><MessageSquare size={16}/><span>Feedback</span>{review.length>0&&<span>({review.length})</span>}</button></div></div>
 <div className="workspace"><aside className="sidebar"><button className="brand-button" aria-label="Go to Today" onClick={()=>go('today')}><Brand logo={logo}/></button><div className="workspace-label">Your little business</div><nav aria-label="Main navigation">{navs.map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>go(id)}><Icon size={19}/><span>{label}</span>{id==='orders'&&data.orders.some(o=>o.status==='Awaiting payment')&&<small>{data.orders.filter(o=>o.status==='Awaiting payment').length}</small>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>go('logos')}>Logo options</button><button onClick={()=>go('website')}><ExternalLink size={17}/>Website concept</button><button onClick={()=>setViewer(x=>!x)}><Eye size={17}/>{viewer?'Patrick · View only':'Owner preview'}</button></div><div className="sidebar-stamp">big finds.<br/>good company.</div></aside>
 <div className="content"><header className="context-bar"><span><LogoImage id={logo} avatar className="context-logo"/>Big Mood Vintage <ChevronRight size={14}/> {navs.find(n=>n[0]===page)?.[1]||(page==='logos'?'Logo options':'Website concept')}</span><button onClick={()=>setOffline(o=>!o)} className={offline?'offline-toggle active':'offline-toggle'}>{offline?<WifiOff size={15}/>:<CheckCircle2 size={15}/>}<span>{offline?'Offline demo':'Saved on this device'}</span></button></header>{viewer&&<div className="viewer-banner"><Eye size={17}/>Patrick’s view-only preview. Switch to Owner in the menu to try changes.</div>}{offline&&<div className="viewer-banner"><WifiOff size={17}/>Offline capture simulation. Real syncing is not connected.</div>}{storageError&&<div className="viewer-banner warning">Device storage is full or unavailable. Keep this tab open and download your feedback now.</div>}
 <main data-page={page} ref={mainRef} id="main" tabIndex="-1" key={page+selected+orderId+customerId}>{page==='logos'?<LogoReview selected={logo} onSelect={setLogo} onComment={()=>setPanel({type:'feedback'})} onTry={go}/>:page==='today'?<Today/>:page==='inventory'?(current?<ItemDetail/>:<Inventory/>):page==='posts'?<Render fn={Posts} key={selected}/>:page==='orders'?(order?<Render fn={OrderDetail} key={orderId}/>:<Orders/>):page==='money'?<Money/>:page==='customers'?<Render fn={Customers} key={customerId}/>:<PublicPage/>}</main>
 <footer className="app-footer"><span>{themes[themeKey].name} · {themes[themeKey].note}</span><button onClick={()=>setResetConfirm(true)}><RotateCcw size={14}/>Reset sample data</button></footer></div></div>
 <nav className="mobile-nav" aria-label="Mobile navigation">{navs.slice(0,5).map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>go(id)}><Icon size={21}/><span>{id==='posts'?'Posts':label}</span></button>)}<button className={page==='customers'?'active':''} onClick={()=>go('customers')}><Users size={21}/><span>Buyers</span></button></nav>
 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}<button aria-label="Dismiss message" onClick={()=>setToast('')}><X size={16}/></button></div>}
 {guide&&<Render fn={Dialog} title="Meet your next little workspace." onClose={()=>{setGuide(false);try{localStorage.setItem(KEY+'.visited','true')}catch{}}}><p>Clubhouse is Jenn’s preferred direction. Try the new sourcing dropdown in Inventory and compare sources in Money. Nothing here touches real inventory, Instagram, banking or paid AI.</p><div className="direction-cards">{Object.entries(themes).map(([k,t])=><button className={`direction-card direction-${k} ${themeKey===k?'chosen':''}`} key={k} onClick={()=>setTheme(k)}><span className="direction-swatch">big mood<span>{k==='label'?'01':k==='studio'?'02':'03'}</span></span><strong>{t.name}</strong><small>{t.description}</small>{themeKey===k&&<Check size={17}/>}</button>)}</div><h3>Try a short walkthrough</h3><ol className="walkthrough"><li>Add a sample find and edit its details.</li><li>Prepare the cardigan’s post and compare its photos.</li><li>Reserve a piece, confirm payment and record pickup.</li><li>Capture a sample receipt and check the money view.</li></ol><p>Use Feedback on any screen. Notes stay on this device until you share or download the feedback file for Patrick.</p><div className="button-row"><Button kind="primary" onClick={()=>{setGuide(false);try{localStorage.setItem(KEY+'.visited','true')}catch{}}}>Explore {themes[themeKey].name} <ArrowRight size={17}/></Button><Button onClick={()=>{setGuide(false);go('website')}}>See website concept</Button></div><details className="review-boundaries"><summary>What is real in this prototype?</summary><p>Navigation, local sample records, captions, order statuses, expense calculations, image downloads and feedback exports work. AI, receipt extraction, authentication, payment, posting and offline sync are demonstrations. Personal data is not needed. Brand name, photo style, delivery pricing and shipping workflow are open for review.</p><Button kind="text" onClick={()=>setViewer(v=>!v)}>{viewer?'Switch to Owner':'Try Patrick’s view-only role'}</Button><Button kind="text" onClick={()=>setOffline(o=>!o)}>{offline?'Turn offline demo off':'Try offline capture demo'}</Button></details></Render>}
 {resetConfirm&&<Render fn={Dialog} title="Reset the sample business?" onClose={()=>setResetConfirm(false)}><p>This restores the original sample items, orders and expenses on this device. Your feedback notes stay saved.</p><div className="button-row"><Button onClick={()=>setResetConfirm(false)}>Keep my changes</Button><Button kind="primary" onClick={()=>{setData(copySeed());setResetConfirm(false);go('today');tell('Sample business reset. Feedback retained.')}}>Reset sample data</Button></div></Render>}
 <Render fn={Panel}/>
 </div>
}
createRoot(document.getElementById('root')).render(<PrototypePreview><App/></PrototypePreview>);
